// ===== 설정 (여기만 수정하세요) =====
const API_KEY = 'AIzaSyDI0pjUJBjW2zorcIDkL7G1LCsd21gNmNQ';
const MAX_VIDEOS_PER_QUERY = 10;          // 검색어당 영상 수 (최대 50)
const PUBLISHED_AFTER = '2022-01-01T00:00:00Z'; // 이 날짜 이후 영상만

// 증상 그룹별 검색어. 유튜브 검색 1회 = 할당량 100 (하루 기본 10,000)
const QUERIES = {
  '냉방불량':   ['LG 에어컨 안 시원함', '휘센 에어컨 안시원해요', '휘센 냉방 약함', 'LG 에어컨 미지근한 바람'],
  '냄새':       ['휘센 에어컨 냄새', 'LG 에어컨 쉰내', '휘센 곰팡이 냄새 청소'],
  '물샘':       ['LG 에어컨 물 떨어짐', '휘센 물샘', '휘센 배수호스 막힘'],
  '소음':       ['LG 에어컨 소음', '휘센 실외기 소음', '휘센 에어컨 딸깍 소리'],
  '에러코드':   ['휘센 에러코드', 'LG 에어컨 CH05', 'LG 에어컨 CH38'],
  '작동이상':   ['휘센 실외기 안 돌아요', 'LG 에어컨 저절로 꺼짐', '휘센 에어컨 전원 안 켜짐'],
  '결빙':       ['LG 에어컨 성에 얼음'],
  '앱·리모컨':  ['LG 씽큐 에어컨 연결 안됨'],
  '청소·관리':  ['휘센 자동건조', 'LG 에어컨 필터 청소', '휘센 셀프 분해 청소'],
  '전기요금':   ['휘센 전기요금 많이 나옴'],
  '설치·냉매':  ['LG 에어컨 설치 불량', '휘센 냉매 가스 충전'],
  'AS·자가진단':['LG 에어컨 AS 후기', 'LG 에어컨 자가진단', '휘센 고장 원인'],
};

const out = [];
for (const [symptom, list] of Object.entries(QUERIES)) {
  for (const q of list) {
    out.push({ json: { query: q, symptom, apiKey: API_KEY, maxResults: MAX_VIDEOS_PER_QUERY, publishedAfter: PUBLISHED_AFTER } });
  }
}
return out;

// 검색 결과 → 영상 목록 (중복 제거, LG 관련 영상만)
const ONLY_LG_VIDEOS = true;
const LG_RE = /LG|엘지|휘센|whisen|오브제|씽큐|thinq|타워|듀얼쿨/i;

const queries = $('검색어 생성').all();
const apiKey = queries[0].json.apiKey;
const decode = s => String(s || '').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');

const map = new Map();
$input.all().forEach((item, i) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : i;
  const q = (queries[idx] || {}).json || {};
  for (const v of (item.json.items || [])) {
    const id = v.id && v.id.videoId;
    if (!id) continue;
    const sn = v.snippet || {};
    const title = decode(sn.title);
    if (ONLY_LG_VIDEOS && !LG_RE.test(title + ' ' + decode(sn.description) + ' ' + decode(sn.channelTitle))) continue;
    if (map.has(id)) { map.get(id).queries.add(q.query); continue; }
    map.set(id, { videoId: id, videoTitle: title, channel: decode(sn.channelTitle), videoPublishedAt: sn.publishedAt, queries: new Set([q.query]) });
  }
});

return [...map.values()].map(v => ({ json: { ...v, queries: [...v.queries].join(' | '), apiKey } }));

// 댓글·답글 펼치기 → 증상 / '원인·다음행동 판단 어려움' 신호 태깅
const MIN_LEN = 8;
const KEEP_ONLY_RELEVANT = true; // 증상 또는 판단어려움 신호가 있는 댓글만 남김

const SYMPTOMS = {
  '냉방불량': /안\s*시원|시원하지\s*않|시원하지가\s*않|냉방이?\s*(약|안\s*돼|안\s*되)|미지근|더운\s*바람|찬\s*바람이?\s*안|온도가?\s*안\s*(내려|떨어)/,
  '냄새': /냄새|쉰내|악취|곰팡|썩은|걸레\s*냄/,
  '물샘': /물이?\s*(새|샘|떨어|뚝뚝|흘러|넘|튀)|누수|물샘|물방울|배수/,
  '소음': /소음|시끄|소리가|소리\s*(나|가\s*나|남)|덜덜|웅웅|윙윙|딸깍|딱딱|진동|떨림|쉭쉭|우웅/,
  '에러코드': /CH\s?-?\d{1,3}|에러\s*코드|오류\s*코드|에러\s*뜨|에러가/i,
  '작동이상': /꺼져|꺼짐|꺼지|안\s*켜|안\s*돌|작동\s*(이\s*)?안|멈춰|멈춤|실외기가?\s*안|켜졌다\s*꺼/,
  '결빙': /성에|얼음|결빙|얼어/,
  '앱·리모컨': /씽큐|thinq|앱\s*(연결|등록)|와이파이|wifi|리모컨/i,
  '청소·관리': /자동\s*건조|필터|청소|세척|분해/,
  '전기요금': /전기\s*(요금|세|료)|누진/,
  '설치': /설치|배관|타공|실외기\s*위치/,
  'AS·서비스': /a\s*\/?\s*s|서비스\s*센터|센터에|기사님?|수리|출장비|상담원|고객\s*센터|접수/i,
  '냉매': /냉매|가스\s*(충전|보충)|가스가?\s*(새|부족|빠)/,
};
const CAUSE_UNSURE = /왜\s*(그런|이러|이렇|그럴|안|자꾸|계속)|원인이|원인을|원인\s*(이\s*)?뭘|뭐가\s*문제|무슨\s*문제|이유가|이유를|고장\s*인가|고장인지|고장\s*난\s*건가|정상\s*인가|정상인지|정상\s*이에요\s*\?|정상이죠|이게\s*맞나|모르겠/;
const ACTION_UNSURE = /어떻게\s*(해야|하면|하나요|하죠|해요\s*\?)|어떡하|어쩌죠|어째야|해야\s*(하나요|할까|되나|돼요|되나요)|불러야|(a\s*\/?\s*s|수리)\s*(를\s*)?(받아야|불러야|신청해야|맡겨야)|방법\s*(이|좀)?\s*(있|알려|없)|해결\s*(방법|이\s*안|못|이\s*안\s*돼)|알려\s*주세요|도와\s*주세요|조언|청소\s*하면\s*되/i;
const ATTEMPTED = /해\s*봤|해봤|했는데|했는데도|했지만|그래도|여전히|그대로|리셋|껐다\s*켜|재부팅|코드\s*뽑|청소\s*(를\s*)?했|기사님?\s*(이\s*)?(왔|불렀|다녀|방문)|수리\s*(를\s*)?(받|했)/;
const QUESTION = /\?|까요|나요|가요|는지|을지|ㄹ지|건가|인가요|되나요/;
const NEGATIVE = /짜증|화나|열받|최악|다시는|후회|환불|교환|돈\s*아까|스트레스|답답|황당|어이없|실망/;

const videos = new Map($('영상 목록 정리').all().map(i => [i.json.videoId, i.json]));
const today = new Date().toISOString().slice(0, 10);
const seen = new Set();
const rows = [];

function add(sn, commentId, isReply, parentText, replyCount, videoId) {
  if (!sn || seen.has(commentId)) return;
  seen.add(commentId);
  const text = String(sn.textOriginal || sn.textDisplay || '').replace(/\s+/g, ' ').trim();
  if (text.length < MIN_LEN) return;
  if (/https?:\/\//.test(text) && /구매|할인|쿠팡|링크/.test(text)) return; // 광고성 제거

  const symptoms = Object.entries(SYMPTOMS).filter(([, re]) => re.test(text)).map(([k]) => k);
  const cause = CAUSE_UNSURE.test(text);
  const action = ACTION_UNSURE.test(text);
  const attempted = ATTEMPTED.test(text);
  const question = QUESTION.test(text);
  const negative = NEGATIVE.test(text);
  if (KEEP_ONLY_RELEVANT && symptoms.length === 0 && !cause && !action) return;

  const v = videos.get(videoId) || {};
  rows.push({ json: {
    '수집일': today,
    '검색어': v.queries || '',
    '영상제목': v.videoTitle || '',
    '채널': v.channel || '',
    '영상URL': `https://www.youtube.com/watch?v=${videoId}`,
    '댓글URL': `https://www.youtube.com/watch?v=${videoId}&lc=${commentId}`,
    '구분': isReply ? '답글' : '댓글',
    '원댓글': isReply ? parentText : '',
    '댓글내용': text,
    '좋아요': sn.likeCount || 0,
    '답글수': isReply ? '' : (replyCount || 0),
    '작성일': String(sn.publishedAt || '').slice(0, 10),
    '증상분류': symptoms.join(', '),
    '원인모름': cause ? 'Y' : '',
    '다음행동모름': action ? 'Y' : '',
    '질문형': question ? 'Y' : '',
    '이미시도한조치': attempted ? 'Y' : '',
    '부정감정': negative ? 'Y' : '',
    '판단어려움후보': (cause || action) && (symptoms.length > 0 || question) ? 'Y' : '',
    '댓글ID': commentId,
  }});
}

for (const item of $input.all()) {
  for (const t of (item.json.items || [])) {
    const s = t.snippet || {};
    const top = s.topLevelComment || {};
    const topText = String((top.snippet || {}).textOriginal || '').replace(/\s+/g, ' ').trim();
    add(top.snippet, top.id, false, '', s.totalReplyCount, s.videoId);
    for (const r of ((t.replies || {}).comments || [])) add(r.snippet, r.id, true, topText.slice(0, 300), 0, s.videoId);
  }
}

// 판단어려움 후보 → 좋아요 많은 순으로 정렬
rows.sort((a, b) => (b.json['판단어려움후보'] === 'Y') - (a.json['판단어려움후보'] === 'Y') || b.json['좋아요'] - a.json['좋아요']);
return rows;
